P(url="/guide/come-scegliere-impresa-ristrutturazione/", hero="re-direttore-lavori",
 title="Come scegliere un’impresa di ristrutturazione: 10 controlli",
 desc="Come scegliere un’impresa di ristrutturazione senza brutte sorprese: preventivo dettagliato, prezzo bloccato, tempi nel contratto, pratiche, assicurazioni e pagamenti a stato avanzamento.",
 ogtitle="Come scegliere un’impresa di ristrutturazione", ogdesc="I 10 controlli da fare prima di firmare un contratto di ristrutturazione.",
 crumbs=[GUIDE, ("Scegliere un’impresa di ristrutturazione", None)], eyebrow="Guida · Ristrutturazioni",
 h1=f"Come scegliere un’impresa di ristrutturazione: {G}10 controlli prima di firmare.{_G}",
 lead="Il preventivo più basso non è sempre il più economico. Ecco cosa verificare in un’impresa e in un contratto di ristrutturazione per evitare ritardi, extra e lavori da rifare.",
 cta1="Richiedi un preventivo", cta2="I controlli",
 sezioni=[
  {"id": "controlli", "tipo": "passi", "eyebrow": "La checklist", "h2": f"I dieci {G}controlli{_G}",
   "corpo": [("1 · Sopralluogo vero", "Diffidate dei preventivi fatti al telefono: l’impresa seria viene a vedere, misura e verifica impianti e strutture."),
             ("2 · Preventivo voce per voce", "Ogni lavorazione con quantità, materiali e marche. Le voci a corpo generiche rendono impossibile il confronto."),
             ("3 · Cosa è escluso", "Smaltimenti, pratiche, ponteggi, pulizia finale, IVA: chiedete per iscritto cosa non è compreso."),
             ("4 · Prezzo bloccato", "Chiedete che il prezzo sia fisso per i lavori descritti e che ogni variante sia quotata prima per iscritto."),
             ("5 · Tempi nel contratto", "Data di inizio, data di fine e cronoprogramma. Senza date scritte, i ritardi non hanno conseguenze."),
             ("6 · Chi coordina", "Un unico referente responsabile evita il rimpallo tra muratore, idraulico ed elettricista."),
             ("7 · Pratiche e bonus", "Chi prepara CILA o SCIA? Chi si occupa dei documenti per le detrazioni? Devono essere chiari prima di iniziare."),
             ("8 · Pagamenti", "Acconto ragionevole e pagamenti a stato di avanzamento lavori, mai l’intero importo in anticipo."),
             ("9 · Documenti finali", "Dichiarazioni di conformità degli impianti, schede dei materiali, garanzie: vanno consegnati a fine lavori."),
             ("10 · Comunicazione", "Come vi aggiornerà durante il cantiere? Foto e avanzamento settimanale sono il segno di un’impresa organizzata.")]},
  {"id": "nostro", "tipo": "testo", "eyebrow": "Il nostro metodo", "h2": f"Come rispondiamo noi {G}a questi controlli{_G}",
   "corpo": ["Danova Real Estate lavora con sopralluogo e preventivo gratuiti, preventivo dettagliato voce per voce, prezzo bloccato, tempi scritti nel contratto, un unico referente e pratiche e bonus gestiti dai nostri tecnici. Trovate il metodo completo nella pagina <a href=\"/ristrutturazioni-chiavi-in-mano/\">ristrutturazioni chiavi in mano</a>."]},
  {"id": "promesse", "tipo": "promesse", "eyebrow": "Le nostre promesse", "h2": f"Quattro impegni {G}per iscritto{_G}"}],
 faq=[("Quanti preventivi conviene chiedere?", "Due o tre, purché confrontabili: stesse lavorazioni, stessi materiali, stesse esclusioni. Altrimenti si confrontano cose diverse."),
      ("È normale pagare un acconto?", "Sì, un acconto per l’ordine dei materiali è normale; il resto va pagato in base all’avanzamento dei lavori, con bonifico parlante se si usano le detrazioni.")],
 ctabox={"h2": "Mettete alla prova il nostro preventivo.", "p": "Sopralluogo gratuito e preventivo voce per voce, senza impegno.", "btn": "Richiedi un preventivo"},
 altri=[("Guida: quanto costa ristrutturare casa", "/guide/quanto-costa-ristrutturare-casa/"), ("Ristrutturazioni chiavi in mano", "/ristrutturazioni-chiavi-in-mano/"), ("Bonus ristrutturazione 2026", "/bonus-ristrutturazione-2026/"), ("Guida: CILA o SCIA", "/guide/cila-o-scia/"), ("Tutte le guide", "/guide/")],
 svc=svc("Guida alla scelta dell’impresa di ristrutturazione", "Guida", "Checklist per scegliere un’impresa di ristrutturazione: sopralluogo, preventivo, prezzo bloccato, tempi, pratiche, pagamenti e documenti finali.", []))

P(url="/guide/cila-o-scia/", hero="re-cantiere-cartongesso",
 title="CILA o SCIA: quale pratica serve per ristrutturare casa",
 desc="CILA o SCIA? Differenze, quando servono, cosa rientra nell’edilizia libera e cosa succede se si fanno lavori senza pratica. Guida pratica per chi ristruttura in Veneto e Friuli.",
 ogtitle="CILA o SCIA: quale serve?", ogdesc="Edilizia libera, CILA e SCIA spiegate in modo semplice, con esempi di lavori.",
 crumbs=[GUIDE, ("CILA o SCIA", None)], eyebrow="Guida · Pratiche edilizie",
 h1=f"CILA o SCIA: {G}quale pratica serve per i vostri lavori.{_G}",
 lead="Prima di aprire un cantiere bisogna capire se i lavori sono edilizia libera, richiedono una CILA o una SCIA. Ecco le differenze con esempi concreti.",
 cta1="Verifichiamo il vostro caso", cta2="Le differenze",
 sezioni=[
  {"id": "differenze", "tipo": "cards", "eyebrow": "Le differenze", "h2": f"Tre livelli, {G}in modo semplice{_G}",
   "corpo": [("Edilizia libera", "Manutenzione ordinaria: tinteggiature, sostituzione di pavimenti e rivestimenti, riparazione di impianti senza modifiche sostanziali. Nessuna pratica, ma conviene documentare i lavori."),
             ("CILA", "Comunicazione di inizio lavori asseverata: manutenzione straordinaria senza toccare le strutture, per esempio spostare tramezzi, rifare impianti, unire o dividere stanze."),
             ("SCIA", "Segnalazione certificata di inizio attività: interventi più rilevanti, per esempio su parti strutturali, o alcune ristrutturazioni edilizie."),
             ("Permesso di costruire", "Per le nuove costruzioni e le trasformazioni più importanti."),
             ("Immobili vincolati", "Possono servire autorizzazioni aggiuntive della Soprintendenza o paesaggistiche."),
             ("Regole locali", "Ogni Comune può avere moduli e procedure proprie: la verifica tecnica è sempre il primo passo.")]},
  {"id": "esempi", "tipo": "testo", "eyebrow": "Esempi", "h2": f"Esempi {G}di lavori comuni{_G}",
   "corpo": ["<b>Rifare il bagno</b> sostituendo solo piastrelle e sanitari nella stessa posizione è in genere manutenzione ordinaria; se si rifanno gli impianti o si sposta la doccia di solito serve una CILA. <b>Creare una stanza</b> con una <a href=\"/pareti-divisorie/\">parete divisoria</a> modifica la distribuzione interna: CILA. <b>Aprire un varco in un muro portante</b> tocca le strutture: SCIA con calcoli strutturali.",
             "Senza la pratica corretta si rischiano sanzioni, problemi nella vendita dell’immobile e la perdita delle detrazioni fiscali. Per questo, nei lavori che seguiamo, le pratiche sono preparate dai nostri tecnici e incluse nel preventivo: <a href=\"/pratiche-edilizie-cila-scia/\">ecco come funziona</a>."]},
  {"id": "tempi", "tipo": "passi", "eyebrow": "Come funziona", "h2": f"Dalla verifica {G}alla fine lavori{_G}",
   "corpo": [("Verifica dell’immobile", "Il tecnico controlla che lo stato attuale corrisponda a quanto depositato in Comune e al catasto: eventuali difformità vanno sanate prima."),
             ("Presentazione della pratica", "CILA e SCIA si presentano online allo Sportello unico per l’edilizia del Comune, firmate dal tecnico e dal proprietario."),
             ("Inizio lavori", "Con la CILA e con la SCIA i lavori possono iniziare dalla presentazione, salvo autorizzazioni aggiuntive (vincoli, strutture, condominio)."),
             ("Durante il cantiere", "Le varianti importanti vanno comunicate; la sicurezza richiede la notifica preliminare quando lavorano più imprese."),
             ("Fine lavori", "Comunicazione di fine lavori, aggiornamento catastale se cambia la planimetria e, quando serve, segnalazione di agibilità.")]},
  {"id": "casi", "tipo": "cards", "eyebrow": "Casi frequenti", "h2": f"Quale pratica {G}per questi lavori{_G}",
   "corpo": [("Tinteggiare e cambiare pavimenti", "Di solito edilizia libera, se non si toccano impianti e distribuzione."),
             ("Rifare bagno e impianti", "Di solito CILA, perché è manutenzione straordinaria."),
             ("Spostare o creare tramezzi", "CILA: cambia la distribuzione interna."),
             ("Cambiare le finestre", "Edilizia libera se forma e dimensioni restano uguali; per l’ecobonus servono comunque i documenti tecnici."),
             ("Rifare il tetto", "CILA se non cambiano forma e altezza; con interventi sulle strutture serve il progetto strutturale."),
             ("Aprire un muro portante", "SCIA con progetto strutturale e deposito delle opere.")]}],
 faq=[("Quanto tempo serve per ottenere la CILA?", "La CILA non si ottiene: si presenta. Una volta depositata dal tecnico i lavori possono iniziare; il tempo dipende soprattutto dalla verifica preliminare dell’immobile e dai documenti da raccogliere."),
      ("Cosa succede se nell’immobile ci sono difformità?", "Vanno regolarizzate prima o insieme ai nuovi lavori, altrimenti la pratica e le detrazioni sono a rischio. Lo verifichiamo all’inizio, con accesso agli atti in Comune."),
      ("Chi presenta la CILA?", "Un tecnico abilitato (geometra, architetto, ingegnere) che assevera la conformità dei lavori, per conto del proprietario."),
      ("La CILA serve per il bonus ristrutturazione?", "Per i lavori di manutenzione straordinaria sì: il titolo edilizio corretto è uno dei documenti alla base della detrazione.")],
 ctabox={"h2": "Non sapete quale pratica serve?", "p": "Diteci lavori e indirizzo: lo verifichiamo noi e prepariamo la pratica.", "btn": "Verifichiamo il vostro caso"},
 altri=[("Pratiche CILA e SCIA", "/pratiche-edilizie-cila-scia/"), ("Bonus ristrutturazione 2026", "/bonus-ristrutturazione-2026/"), ("Pareti divisorie", "/pareti-divisorie/"), ("Tutte le guide", "/guide/")],
 svc=svc("Guida CILA o SCIA", "Guida", "Differenze tra edilizia libera, CILA, SCIA e permesso di costruire, con esempi di lavori comuni.", []))

P(url="/guide/ristrutturare-un-hotel/", hero="re-camera-hotel-mare",
 title="Ristrutturare un hotel: fasi, tempi e calendario della stagione",
 desc="Come ristrutturare un hotel senza perdere la stagione: quando progettare, quando ordinare gli arredi, come organizzare il cantiere a lotti e cosa preparare per la riapertura.",
 ogtitle="Ristrutturare un hotel: la guida", ogdesc="Fasi, tempi e calendario per rinnovare un hotel tra una stagione e l’altra.",
 crumbs=[GUIDE, ("Ristrutturare un hotel", None)], eyebrow="Guida · Hospitality",
 h1=f"Ristrutturare un hotel: {G}il calendario per non perdere la stagione.{_G}",
 lead="Un hotel ha una finestra di lavoro precisa. Ecco come incastrare progetto, pratiche, ordini, cantiere e arredi perché la data di riapertura non si sposti.",
 cta1="Pianifichiamo i lavori", cta2="Il calendario",
 sezioni=[
  {"id": "calendario", "tipo": "passi", "eyebrow": "Il calendario", "h2": f"Dodici mesi, {G}cinque fasi{_G}",
   "corpo": [("Durante la stagione: obiettivi e sopralluogo", "Che categoria volete raggiungere? Quali camere rendono meno? Il sopralluogo si fa con l’hotel aperto."),
             ("Fine stagione: progetto e preventivo", "Progetto, render e preventivo a prezzo bloccato, con cronoprogramma fino alla riapertura."),
             ("Prima della chiusura: pratiche e ordini", "Titoli edilizi, eventuali pratiche antincendio e ordini di arredi e materiali con tempi di produzione lunghi."),
             ("Chiusura: cantiere", "Squadre in parallelo su piani o lotti di camere, con un responsabile sempre presente."),
             ("Prima della riapertura: allestimento e marketing", "Montaggio arredi, pulizia, foto e video delle camere nuove, aggiornamento di sito e portali.")]},
  {"id": "consigli", "tipo": "cards", "eyebrow": "Consigli pratici", "h2": f"Errori {G}da evitare{_G}",
   "corpo": [("Ordinare tardi gli arredi", "I tempi di produzione sono il collo di bottiglia: si ordina prima della chiusura."),
             ("Fornitori separati", "Edile, impianti, arredi e porte REI con contratti diversi: nessuno risponde dei ritardi altrui."),
             ("Dimenticare le norme", "Antincendio, accessibilità e acustica vanno considerate nel progetto, non a fine lavori."),
             ("Riaprire con le foto vecchie", "Le camere nuove devono essere online prima della riapertura per alzare il prezzo medio."),
             ("Materiali non adatti", "Nel contract servono materiali resistenti all’uso intensivo e facili da pulire."),
             ("Nessun piano B", "Un cronoprogramma con margini e lotti permette di riaprire anche se un piano richiede più tempo.")]},
  {"id": "link", "tipo": "testo", "eyebrow": "Approfondimenti", "h2": f"Come possiamo {G}aiutarvi{_G}",
   "corpo": ["Seguiamo l’intero percorso con la <a href=\"/ristrutturazione-hotel/\">ristrutturazione hotel</a>, l’<a href=\"/arredo-hotel-contract/\">arredo contract</a> e il pacchetto <a href=\"/hotel-chiavi-in-mano/\">hotel chiavi in mano</a>, che aggiunge foto, sito web e gestionale."]}],
 faq=[("Si può ristrutturare con l’hotel aperto?", "Sì, per lotti di camere o per piani, separando i percorsi e concentrando i lavori rumorosi negli orari concordati."),
      ("Quanto tempo prima bisogna iniziare a progettare?", "Idealmente durante la stagione precedente, così ordini e pratiche sono pronti per l’inizio della chiusura.")],
 ctabox={"h2": "Pianifichiamo la vostra prossima chiusura.", "p": "Struttura, camere e date di chiusura: vi proponiamo un cronoprogramma.", "btn": "Pianifichiamo i lavori"},
 altri=[("Ristrutturazione hotel", "/ristrutturazione-hotel/"), ("Arredo hotel e contract", "/arredo-hotel-contract/"), ("Guida: porte REI negli hotel", "/guide/porte-rei-negli-hotel/"), ("Tutte le guide", "/guide/")],
 svc=svc("Guida alla ristrutturazione di un hotel", "Guida", "Fasi, tempi ed errori da evitare per ristrutturare un hotel tra una stagione e l’altra.", []))

P(url="/guide/quando-conviene-il-cappotto-termico/", hero="re-facciata-cantiere",
 title="Quando conviene il cappotto termico? Vantaggi, limiti e bonus",
 desc="Quando conviene fare il cappotto termico: tipo di edificio, risparmio, comfort estivo, muffe, detrazioni 2026 e alternative come cappotto interno e facciata ventilata.",
 ogtitle="Quando conviene il cappotto termico", ogdesc="Vantaggi, limiti, detrazioni 2026 e alternative al cappotto esterno.",
 crumbs=[GUIDE, ("Quando conviene il cappotto termico", None)], eyebrow="Guida · Efficienza energetica",
 h1=f"Quando conviene il cappotto termico: {G}vantaggi, limiti e bonus.{_G}",
 lead="Il cappotto è uno degli interventi più efficaci per ridurre i consumi, ma non è sempre la scelta giusta. Ecco come capire se conviene sul vostro edificio.",
 cta1="Valutiamo il vostro edificio", cta2="Quando conviene",
 sezioni=[
  {"id": "quando", "tipo": "cards", "eyebrow": "Quando conviene", "h2": f"I casi {G}in cui rende di più{_G}",
   "corpo": [("Edifici non isolati", "Case e condomini costruiti prima degli anni ’90, con muri senza isolante: il guadagno è massimo."),
             ("Facciata da rifare comunque", "Se la facciata va già ripristinata o tinteggiata, aggiungere l’isolamento costa relativamente meno."),
             ("Muffe agli angoli", "Il cappotto alza la temperatura delle pareti interne e riduce la condensa."),
             ("Case molto esposte", "Pareti a nord o molto soleggiate: comfort migliore d’inverno e d’estate."),
             ("Prima di cambiare caldaia", "Isolare prima permette di installare un impianto più piccolo ed efficiente."),
             ("Con le detrazioni attive", "Nel 2026 l’ecobonus è al 50% per l’abitazione principale e al 36% per gli altri immobili.")]},
  {"id": "limiti", "tipo": "testo", "eyebrow": "I limiti", "h2": f"Quando valutare {G}alternative{_G}",
   "corpo": ["Nei <b>centri storici vincolati</b> spesso la facciata non si può modificare: si può isolare dall’interno con contropareti in cartongesso. Dove serve un rivestimento di pregio o molta protezione dal caldo, la <a href=\"/facciate-ventilate-e-rifacimento-facciate/\">facciata ventilata</a> è un’alternativa più costosa ma molto durevole.",
             "Il risultato dipende dalla posa: angoli, davanzali, balconi e raccordi con i serramenti sono i punti critici. Leggete come lavoriamo nella pagina <a href=\"/cappotto-termico/\">cappotto termico</a>."]},
  {"id": "svantaggi", "tipo": "testo", "eyebrow": "Gli svantaggi", "h2": f"Cosa sapere {G}prima di decidere{_G}",
   "corpo": ["Il <b>costo iniziale</b> è l’aspetto che pesa di più: servono ponteggi, un sistema certificato e una posa accurata. Le detrazioni ne recuperano una parte, ma conviene valutare il risparmio reale sul vostro edificio con una diagnosi.",
             "Lo <b>spessore</b> si vede: davanzali, soglie, gronde e pluviali vanno adattati, e vicino ai confini bisogna verificare distanze e regole comunali (le norme sull’efficienza energetica permettono in genere di non conteggiare gli spessori dell’isolamento entro certi limiti).",
             "Sulle <b>facciate in mattoni a vista o in cortina</b> il cappotto esterno copre il paramento. Le alternative sono il cappotto con finitura in listelli che riproducono il mattone, l’<a href=\"/isolamento-sottotetto/\">insufflaggio</a> nell’intercapedine quando il muro è a cassa vuota, oppure il <a href=\"/cappotto-termico/\">cappotto interno</a>.",
             "Infine conta la <b>qualità della posa</b>: un cappotto posato male, con pannelli non tassellati, angoli senza rinforzi o raccordi trascurati intorno alle finestre, può creare crepe e ponti termici. Per questo usiamo sistemi certificati completi."]},
  {"id": "isolanti", "tipo": "cards", "eyebrow": "Quale isolante", "h2": f"Il miglior isolante {G}dipende dall’edificio{_G}",
   "corpo": [("EPS grafitato", "Il più diffuso: leggero, isolante e conveniente. Ideale su case e condomini senza esigenze particolari."),
             ("Lana di roccia", "Incombustibile e traspirante: la scelta per edifici alti, vie di fuga e dove serve più sicurezza al fuoco."),
             ("Fibra di legno", "Ottima per il caldo estivo e per le case in legno; più spessa a parità di isolamento."),
             ("Sughero", "Naturale e stabile, adatto anche a zoccolature ed edifici storici."),
             ("Aerogel", "Pochi millimetri per isolare dove lo spazio manca, per esempio su spalle delle finestre e balconi; costa di più."),
             ("XPS per lo zoccolo", "Pannelli resistenti all’acqua per la parte bassa della facciata, a contatto con il terreno.")]},
  {"id": "zona", "tipo": "testo", "eyebrow": "In Veneto e Friuli", "h2": f"Spessori e requisiti {G}nella nostra zona{_G}",
   "corpo": ["Gran parte del Veneto e del Friuli Venezia Giulia ricade nella <b>zona climatica E</b>, le località di montagna come Belluno e Cortina nella <b>zona F</b>. Per accedere all’ecobonus la parete isolata deve rispettare un valore massimo di <b>trasmittanza</b> fissato per ogni zona: lo spessore dell’isolante si calcola da lì, in base al muro esistente e al materiale scelto.",
             "Con i materiali più comuni servono di solito alcuni centimetri in più nelle zone montane. Al sopralluogo misuriamo il muro, verifichiamo il tipo di supporto e vi diamo spessore e stratigrafia scritti nel preventivo."]}],
 faq=[("Si può fare il cappotto su una facciata in mattoni a vista?", "Sì, con una finitura in listelli che riproducono il mattone; in alternativa si isola dall’interno o, se il muro ha un’intercapedine, con l’insufflaggio. Al sopralluogo verifichiamo quale soluzione è possibile."),
      ("Il cappotto toglie luce alle finestre?", "Le spalle delle finestre diventano un po’ più profonde. Si limita l’effetto con isolanti sottili sulle spalle e, quando si cambiano anche i serramenti, posandoli più verso l’esterno."),
      ("Il cappotto fa risparmiare anche d’estate?", "Sì, riduce il calore che entra dalle pareti; con isolanti ad alta densità, come la fibra di legno, il comfort estivo migliora ancora."),
      ("Serve il permesso del condominio?", "Sì, per le facciate condominiali serve una delibera dell’assemblea.")],
 ctabox={"h2": "Conviene sul vostro edificio?", "p": "Indirizzo e anno di costruzione: veniamo a vedere e ve lo diciamo.", "btn": "Valutiamo il vostro edificio"},
 altri=[("Isolamento sottotetto", "/isolamento-sottotetto/"), ("Cappotto termico", "/cappotto-termico/"), ("Bonus ristrutturazione 2026", "/bonus-ristrutturazione-2026/"), ("Facciate ventilate", "/facciate-ventilate-e-rifacimento-facciate/"), ("Tutte le guide", "/guide/")],
 svc=svc("Guida al cappotto termico", "Guida", "Quando conviene il cappotto termico, limiti, detrazioni 2026 e alternative.", []))

